const inventoryListLevels = `-- name: InventoryListLevels :many
select l.warehouse_id, l.variant_id, l.condition, l.owner_seller_id, l.on_hand, l.reserved, l.reorder_point, l.bin_id, l.updated_at, v.sku, v.name as variant_name, p.name as product_name, w.code as warehouse_code, (l.on_hand - l.reserved) as available
from inventory.inventory_levels l
join catalog.product_variants v on v.id = l.variant_id
join catalog.products p on p.id = v.product_id
join inventory.warehouses w on w.id = l.warehouse_id
where ($2::uuid is null or l.warehouse_id = $2)
  and ($3::uuid is null or l.variant_id = $3)
order by p.name, v.name
limit $1
`

