const inventoryReserveSellerStock = `-- name: InventoryReserveSellerStock :one
update catalog.listings set seller_stock = seller_stock - $1::int
where id = $2 and seller_stock >= $1::int
returning seller_stock
`

type InventoryReserveSellerStockParams struct {
	Qty       int32     `json:"qty"`
	ListingID uuid.UUID `json:"listingId"`
}

// Seller-held stock: conditional decrement of the listing's stock counter.
func (q *Queries) InventoryReserveSellerStock(ctx context.Context, arg InventoryReserveSellerStockParams) (*int32, error) {
	row := q.db.QueryRow(ctx, inventoryReserveSellerStock, arg.Qty, arg.ListingID)
	var seller_stock *int32
	err := row.Scan(&seller_stock)
	return seller_stock, err
}

const inventoryReserveWarehouse = `-- name: InventoryReserveWarehouse :one
update inventory.inventory_levels t
set reserved = t.reserved + $1::int, updated_at = now()
where (t.warehouse_id, t.variant_id, t.condition, t.owner_seller_id) = (
  select il.warehouse_id, il.variant_id, il.condition, il.owner_seller_id from inventory.inventory_levels il
  where il.variant_id = $2 and il.condition = $3 and il.owner_seller_id = $4 and il.on_hand - il.reserved >= $1::int
  order by (il.warehouse_id = $5::uuid) desc nulls last, il.on_hand - il.reserved desc
  limit 1
  for update)
  and t.on_hand - t.reserved >= $1::int
returning t.warehouse_id
`

type InventoryReserveWarehouseParams struct {
	Qty                int32      `json:"qty"`
	VariantID          uuid.UUID  `json:"variantId"`
	Condition          string     `json:"condition"`
	OwnerSellerID      uuid.UUID  `json:"ownerSellerId"`
	PreferredWarehouse *uuid.UUID `json:"preferredWarehouse"`
}

// Race-free reservation: only succeeds if enough unreserved stock exists in one row.
func (q *Queries) InventoryReserveWarehouse(ctx context.Context, arg InventoryReserveWarehouseParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, inventoryReserveWarehouse,
		arg.Qty,
		arg.VariantID,
		arg.Condition,
		arg.OwnerSellerID,
		arg.PreferredWarehouse,
	)
	var warehouse_id uuid.UUID
	err := row.Scan(&warehouse_id)
	return warehouse_id, err
}

